def walk(o):
    if isinstance(o,dict):
        if 'name' in o and ('columns' in o or 'fields' in o):
            yield o
        for v in o.values(): yield from walk(v)
    elif isinstance(o,list):
        for v in o: yield from walk(v)
tabs=list(walk(d))
print(len(tabs))
for t in tabs[:200]:
    print(t.get('name'), len(t.get('columns') or t.get('fields') or []))
